<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role(['student','counselor']);verify_csrf();$uid=(int)user()['id'];$taskId=(int)($_POST['task_id']??0);$stmt=$con->prepare('SELECT t.*,s.id simulation_id FROM simulation_tasks t JOIN career_simulations s ON s.id=t.simulation_id WHERE t.id=? AND s.is_active=1');$stmt->bind_param('i',$taskId);$stmt->execute();$task=$stmt->get_result()->fetch_assoc();if(!$task)json_response(['ok'=>false,'message'=>'Task not found.'],404);
$optionId=null;$response=trim($_POST['response_text']??'');$score=0;$feedback='Response saved.';$aiFeedback=null;
if(in_array($task['task_type'],['scenario_choice','case_study'])){$optionId=(int)($_POST['option_id']??0);$stmt=$con->prepare('SELECT * FROM task_options WHERE id=? AND task_id=?');$stmt->bind_param('ii',$optionId,$taskId);$stmt->execute();$option=$stmt->get_result()->fetch_assoc();if(!$option)json_response(['ok'=>false,'message'=>'Select a valid option.'],422);$score=max(0,(int)$option['score_value']);$feedback=$option['feedback_text']?:'Answer recorded.';}elseif($response==='')json_response(['ok'=>false,'message'=>'Enter your response.'],422);else{$aiFeedback=groq_chat([['role'=>'system','content'=>'You are a supportive career simulation coach. Give 2-4 sentences of specific, constructive feedback. Comment only on the response and task; never request personal information.'],['role'=>'user','content'=>"Task: {$task['title']}\nInstructions: {$task['instructions']}\nStudent response: $response"]],['max_tokens'=>220,'timeout'=>12]);$aiFeedback??='AI feedback is temporarily unavailable. Your response was saved successfully.';$feedback=$aiFeedback;$_SESSION['latest_ai_feedback']=$aiFeedback;}
$seconds=min(86400,max(0,(int)($_POST['time_spent_seconds']??0)));$con->begin_transaction();try{$del=$con->prepare('DELETE FROM user_task_attempts WHERE user_id=? AND task_id=?');$del->bind_param('ii',$uid,$taskId);$del->execute();$ins=$con->prepare('INSERT INTO user_task_attempts(user_id,task_id,selected_option_id,response_text,ai_feedback,score_earned,time_spent_seconds) VALUES(?,?,?,?,?,?,?)');$ins->bind_param('iiissii',$uid,$taskId,$optionId,$response,$aiFeedback,$score,$seconds);$ins->execute();
$sid=(int)$task['simulation_id'];$stmt=$con->prepare('SELECT COALESCE(SUM(a.score_earned),0) total,COALESCE(SUM(t.max_score),0) max_score,COUNT(DISTINCT a.task_id) done,(SELECT COUNT(*) FROM simulation_tasks WHERE simulation_id=?) tasks FROM simulation_tasks t LEFT JOIN user_task_attempts a ON a.task_id=t.id AND a.user_id=? WHERE t.simulation_id=?');$stmt->bind_param('iii',$sid,$uid,$sid);$stmt->execute();$x=$stmt->get_result()->fetch_assoc();$complete=(int)$x['done']>=(int)$x['tasks'];$status=$complete?'completed':'in_progress';$stmt=$con->prepare("UPDATE user_simulation_progress SET status=?,total_score=?,max_possible_score=?,completed_at=IF(?='completed',NOW(),NULL) WHERE user_id=? AND simulation_id=?");$stmt->bind_param('siisii',$status,$x['total'],$x['max_score'],$status,$uid,$sid);$stmt->execute();$con->commit();if($complete){award_badges($con,$uid);generate_recommendations($con,$uid);}json_response(['ok'=>true,'message'=>$feedback,'reload'=>true]);}catch(Throwable $e){$con->rollback();json_response(['ok'=>false,'message'=>'Could not save this task.'],500);}
